//! 📸️ Native optional text candidates preserve full paged owners and measured replacement retirement.
use super::*;
use crate::test_source_custody;
fn grant(turn:usize)->RetainedCloneGrant{match turn%3{0=>RetainedCloneGrant::one_capacity_turn(4096,128),1=>RetainedCloneGrant::one_payload_turn(4096,128),_=>RetainedCloneGrant::one_release_turn(4096,128)}}
fn observed(permit:RetainedCloneGrant,action:impl FnOnce()->Result<RetainedCloneStep,ValueError>)->RetainedCloneStep{let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(action);let step=result.unwrap();let progress=step.progress();assert!(progress.fits(permit));assert!(!heap.overflowed);assert!(heap.requested_bytes<=progress.retained_capacity_bytes,"unadmitted text candidate allocation {heap:?} {step:?}");assert!(heap.released_bytes<=progress.released_bytes,"unadmitted text candidate release {heap:?} {step:?}");assert!(progress.copied_bytes+progress.retained_capacity_bytes+progress.released_bytes<=4096);step}
fn close<T:Puzzle2dTextCandidateIntent>(cursor:&mut Puzzle2dTextCandidateCursor<T>){
 cursor.begin_close();for _ in 0..1000000{
  if cursor.terminal_is_empty(){return}
  let copy=cursor.next_close_copy_byte_demand().unwrap();let capacity=cursor.next_close_capacity_byte_demand(copy).unwrap();let release=cursor.next_close_release_byte_demand().unwrap();let depth=cursor.next_close_depth_demand().unwrap();assert!(copy+capacity+release<=4096);
  let permit=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:copy,maximum_capacity_bytes:capacity,maximum_release_bytes:release,maximum_depth:depth};
  assert_eq!(observed(Default::default(),||cursor.close_step(Default::default())).progress(),RetainedCloneProgress::default());
  for axis in 0..4{let mut below=permit;let demand=match axis{0=>&mut below.maximum_copy_bytes,1=>&mut below.maximum_capacity_bytes,2=>&mut below.maximum_release_bytes,_=>&mut below.maximum_depth};if *demand==0{continue}*demand-=1;let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.close_step(below));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(!heap.overflowed);match result{Ok(step)=>assert_eq!(step.progress(),RetainedCloneProgress::default()),Err(error)=>assert!(axis==3&&error.kind==ValueRefusalKind::DepthLimit)}assert_eq!((cursor.next_close_copy_byte_demand().unwrap(),cursor.next_close_capacity_byte_demand(copy).unwrap(),cursor.next_close_release_byte_demand().unwrap(),cursor.next_close_depth_demand().unwrap()),(copy,capacity,release,depth));}
  observed(permit,||cursor.close_step(permit));
 }panic!("optional text candidate did not close")
}
fn retire(snapshot:Puzzle2dSnapshot){let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||ControlledRetirement::new(snapshot));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let mut owner=match result{Ok(owner)=>owner,Err((error,_))=>panic!("{error:?}")};for turn in 0..1000000{if owner.terminal_is_empty(){return}let g=grant(turn);observed(g,||owner.step(g));}panic!("returned text snapshot did not retire")}
fn law<T:Puzzle2dTextCandidateIntent+Clone>(snapshot:&Puzzle2dSnapshot,payload:T,status:&str,expected:Option<&Puzzle2dSnapshot>){
 assert!(size_of::<Puzzle2dTextCandidateCursor<T>>()<=4096);let original=serde_json::to_value(snapshot).unwrap();let mut source=test_source_custody::admit();let mut mutation=test_source_custody::admit();let(mut cursor,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(Puzzle2dTextCandidateCursor::<T>::default);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(observed(RetainedCloneGrant::default(),||cursor.advance(source.borrow(snapshot),mutation.borrow(&payload),RetainedCloneGrant::default())).progress(),RetainedCloneProgress::default());
 let mut complete=false;for turn in 0..1000000{let g=grant(turn);if matches!(observed(g,||cursor.advance(source.borrow(snapshot),mutation.borrow(&payload),g)),RetainedCloneStep::Complete(_)){complete=true;break}}assert!(complete);let output=cursor.take().unwrap();assert_eq!(match output.plan.disposition{Puzzle2dTextDisposition::Changed=>"changed",Puzzle2dTextDisposition::NoOp=>"noOp",Puzzle2dTextDisposition::TargetMissing=>"targetMissing"},status);assert_eq!(output.snapshot.as_ref().map(|value|serde_json::to_value(value).unwrap()),expected.map(|value|serde_json::to_value(value).unwrap()));assert!(cursor.take().is_none());close(&mut cursor);if let Some(snapshot)=output.snapshot{retire(snapshot)}
 for pause in [0,1,3,7,17,100]{let mut cursor=Puzzle2dTextCandidateCursor::<T>::default();for turn in 0..pause{let g=grant(turn);if matches!(observed(g,||cursor.advance(source.borrow(snapshot),mutation.borrow(&payload),g)),RetainedCloneStep::Complete(_)){break}}close(&mut cursor)}
 if expected.is_some(){for phase in [2,4,6,8]{let mut cursor=Puzzle2dTextCandidateCursor::<T>::default();let mut reached=false;for turn in 0..1000000{let g=grant(turn);let step=observed(g,||cursor.advance(source.borrow(snapshot),mutation.borrow(&payload),g));if cursor.phase==phase{reached=true;break}assert!(!matches!(step,RetainedCloneStep::Complete(_)))}assert!(reached);close(&mut cursor)}}
 let mut cursor=Puzzle2dTextCandidateCursor::<T>::default();observed(grant(1),||cursor.advance(source.borrow(snapshot),mutation.borrow(&payload),grant(1)));let swapped=payload.clone();assert!(cursor.advance(source.borrow(snapshot),mutation.borrow(&swapped),grant(1)).is_err());close(&mut cursor);assert_eq!(serde_json::to_value(snapshot).unwrap(),original);test_source_custody::close(&mut source);test_source_custody::close(&mut mutation);
}
#[test]
fn history_edit_puzzle2d_optional_text_candidate_preserves_full_paged_snapshot_and_displaced_owner_cancel(){
 let corpus:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let full:serde_json::Value=serde_json::from_str(include_str!("../../../../../../🚪️io/🪶️sqlite/📸️snapshot/🧫️fixtures/🔣️.json")).unwrap();
 for row in corpus["cases"].as_array().unwrap(){let mut snapshot:Puzzle2dSnapshot=serde_json::from_value(full["snapshot"].clone()).unwrap();let id=if row["target"].as_bool().unwrap(){"retained"}else{"missing"}.into();let previous=row["before"].as_str().map(PagedUtf8::from);let next=row["next"].as_str().map(PagedUtf8::from);let status=row["expected"].as_str().unwrap();if row["role"]=="nodeIcon"{snapshot.nodes.clear();snapshot.nodes.push(crate::Puzzle2dNode{id:"retained".into(),icon_kind:previous,text:Some("untouched\0😀".repeat(1300).into()),..Default::default()});snapshot.nodes.push(crate::Puzzle2dNode{id:"retained".into(),icon_kind:Some("second owner".into()),..Default::default()});let expected=if status=="changed"{let mut expected=snapshot.clone();expected.nodes.get_mut(0).unwrap().icon_kind=next.clone();Some(expected)}else{None};law(&snapshot,ChangeNodeIcon{id,new_icon_kind:next},status,expected.as_ref())}else{snapshot.target_regions.clear();snapshot.target_regions.push(crate::Puzzle2dTargetRegion{id:"retained".into(),label:previous,..Default::default()});snapshot.target_regions.push(crate::Puzzle2dTargetRegion{id:"retained".into(),label:Some("second owner".into()),..Default::default()});let expected=if status=="changed"{let mut expected=snapshot.clone();expected.target_regions.get_mut(0).unwrap().label=next.clone();Some(expected)}else{None};law(&snapshot,EditTargetRegionLabel{id,new_label:next},status,expected.as_ref())}}
 let text="😀\0甲".repeat(20000);let mut snapshot:Puzzle2dSnapshot=serde_json::from_value(full["snapshot"].clone()).unwrap();snapshot.nodes.clear();snapshot.nodes.push(crate::Puzzle2dNode{id:"retained".into(),icon_kind:Some(text.into()),..Default::default()});let mut expected=snapshot.clone();expected.nodes.get_mut(0).unwrap().icon_kind=Some("replacement".into());law(&snapshot,ChangeNodeIcon{id:"retained".into(),new_icon_kind:Some("replacement".into())},"changed",Some(&expected));eprintln!("[DEBUG] fourteen optional text candidates retain full original paged snapshots, first-owner semantics and160000byte displaced UTF8; constructor0, each actual copy/capacity/release4096 and four body-stage cancellation boundaries");
}
